export const geoVector=(lat,lon,r=1)=>new THREE.Vector3(Math.cos(lat*Math.PI/180)*Math.cos(lon*Math.PI/180)*r,Math.sin(lat*Math.PI/180)*r,-Math.cos(lat*Math.PI/180)*Math.sin(lon*Math.PI/180)*r);
