 setMode(mode){this.mode=mode;this.sceneType=mode==='interior'?'interior':'globe';this.root.visible=true;this.detailGroup.visible=false;this.interiorGroup.visible=mode==='interior';this.earthGroup.visible=mode!=='interior';this.boundaryGroup.visible=['tectonics','events','expeditions'].includes(mode);this.highlightGroup.visible=mode==='tectonics';this.eventGroup.visible=mode==='events';this.pinGroup.visible=mode==='planet'||mode==='expeditions';this.paleo.visible=mode==='history';this.earth.visible=mode!=='history';this.clouds.visible=mode==='planet'&&this.cloudOn!==false;this.atmosphere.visible=mode!=='history'&&this.atmoOn!==false;this.uniforms.uOpacity.value=1;this.earthMaterial.transparent=false;this.earthMaterial.depthWrite=true;this.controls.minDistance=mode==='interior'?2.1:1.55;this.controls.maxDistance=8;this.controls.target.set(0,0,0);this.labels=[];this.renderLabels();if(mode==='interior')this.focusCartesian(new THREE.Vector3(0,.35,3.9));}
