 highlightPlate(feature){this.clear(this.highlightGroup);if(!feature)return;const polys=feature.geometry.type==='MultiPolygon'?feature.geometry.coordinates:[feature.geometry.coordinates];for(const rings of polys)for(const line of rings){const pts=line.map(([lon,lat])=>geoVector(lat,lon,1.01));this.highlightGroup.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts),new THREE.LineBasicMaterial({color:0xf4d392,transparent:true,opacity:1})));}}
