 setPin(place){this.clear(this.pinGroup);this.labels=[];if(!place){this.renderLabels();return;}const p=geoVector(place.lat,place.lon,1.01);const sphere=new THREE.Mesh(new THREE.SphereGeometry(.012,12,8),new THREE.MeshBasicMaterial({color:0xa7f2dd}));sphere.position.copy(p);this.pinGroup.add(sphere);const line=new THREE.Line(new THREE.BufferGeometry().setFromPoints([p,geoVector(place.lat,place.lon,1.1)]),new THREE.LineBasicMaterial({color:0xa7f2dd}));this.pinGroup.add(line);this.labels.push({text:place.name,point:geoVector(place.lat,place.lon,1.16),group:this.root,occlude:true});this.renderLabels();}
 setEvents(events){this.clear(this.eventGroup);this.events=events;const geom=new THREE.SphereGeometry(1,10,7);const mat=new THREE.MeshBasicMaterial({color:0xe5a66c});const mesh=new THREE.InstancedMesh(geom,mat,events.length);const obj=new THREE.Object3D(),color=new THREE.Color();for(let i=0;i<events.length;i++){const e=events[i],c=e.geometry.coordinates;obj.position.copy(geoVector(c[1],c[0],1.012));obj.scale.setScalar(.005+Math.max(0,e.properties.mag||0)*.002);obj.updateMatrix();mesh.setMatrixAt(i,obj.matrix);color.set(c[2]>300?'#a69cdf':c[2]>70?'#ddbe77':'#e8986b');mesh.setColorAt(i,color);}mesh.userData={type:'events'};this.eventGroup.add(mesh);this.eventInstances=mesh;}
