  if(type==='divergence'){for(const side of [-1,1]){const plate=this.block(1.32,.2,1.25,'#6099a4');plate.position.set(side*.78,.01,0);this.detailGroup.add(plate);this.detailObjects[side===-1?'left':'right']=plate;}const magma=new THREE.Mesh(new THREE.ConeGeometry(.26,.75,24),new THREE.MeshStandardMaterial({color:'#eead65',emissive:'#782b08',emissiveIntensity:.3}));magma.position.y=-.28;this.detailGroup.add(magma);this.labels=[{text:'Neue ozeanische Kruste',point:new THREE.Vector3(0,.3,.62)},{text:'Aufsteigendes Material',point:new THREE.Vector3(0,-.53,.7)}];}
